 (100, 'JR-2026-0100', 6, 1, 1, 1, NULL, 'Trotoar Amblas Membahayakan Pejalan Kaki', 'Trotoar amblas dan miring, rawan membuat pejalan kaki terpeleset terutama lansia dan anak sekolah.', 'Samping Masjid, Jl. Tamansari, Coblong', -6.880777, 107.612828, 'sedang', 1, 'pending', NULL, 'sedang', '2026-11-11 08:00:59', '2026-11-17 08:00:59', NULL, 0, NULL, '2026-11-10 08:00:59', '2026-11-10 08:00:59'),
 (101, 'JR-2026-0101', 8, 1, 10, 1, 2, 'Lubang Besar Mengganggu Arus Lalu Lintas', 'Lubang berukuran hampir satu meter membuat kendaraan menyempit ke satu lajur dan menimbulkan antrean pada jam sibuk.', 'Depan Pasar Jl. Jakarta, Batununggal', -6.927597, 107.634051, 'bahaya', 0, 'proses', NULL, 'darurat', '2026-11-09 18:37:08', '2026-11-12 06:37:08', '2026-11-09 07:18:19', 0, NULL, '2026-11-09 06:37:08', '2026-11-09 07:19:19'),
 (102, 'JR-2026-0102', 11, 5, 1, 4, 2, 'Marka Jalan Hilang Setelah Pengaspalan', 'Setelah pengaspalan ulang, marka jalan belum dicat kembali sehingga arus kendaraan tidak teratur.', 'Depan Pasar Jl. Sangkuriang, Coblong', -6.886705, 107.613202, 'sedang', 0, 'selesai', '2026-10-29 18:46:06', 'sedang', '2026-10-25 17:27:36', '2026-10-31 17:27:36', '2026-10-25 06:22:05', 0, NULL, '2026-10-24 17:27:36', '2026-10-29 18:47:06'),
 (103, 'JR-2026-0103', 5, 6, 3, 5, 2, 'Pohon Tumbang Menutup Jalan', 'Pohon besar tumbang setelah angin kencang dan menutup sebagian jalan serta jalur pejalan kaki.', 'Jl. Sukajadi No. 3 (depan minimarket), Sukajadi', -6.891605, 107.600104, 'bahaya', 0, 'selesai', '2026-09-17 22:25:12', 'darurat', '2026-09-17 15:28:59', '2026-09-20 03:28:59', '2026-09-17 12:38:27', 0, NULL, '2026-09-17 03:28:59', '2026-09-17 22:26:12'),
 (104, 'JR-2026-0104', 6, 6, 6, 5, 2, 'Pohon Lapuk Mengancam Pengguna Jalan', 'Pohon di tepi jalan sudah lapuk dan miring, dikhawatirkan tumbang menimpa kendaraan.', 'Simpang Jl. Pasirkoja, Astana Anyar', -6.93526, 107.599516, 'sedang', 0, 'selesai', '2026-09-17 12:41:13', 'sedang', '2026-09-12 23:08:35', '2026-09-18 23:08:35', '2026-09-12 19:16:56', 0, NULL, '2026-09-11 23:08:35', '2026-09-17 12:42:13'),
 (105, 'JR-2026-0105', 17, 6, 3, 5, 2, 'Pohon Lapuk Mengancam Pengguna Jalan', 'Pohon di tepi jalan sudah lapuk dan miring, dikhawatirkan tumbang menimpa kendaraan.', 'Depan Pasar Jl. Dr. Djunjunan, Sukajadi', -6.892553, 107.599868, 'sedang', 0, 'proses', NULL, 'sedang', '2026-11-09 08:42:58', '2026-11-15 08:42:58', '2026-11-08 20:53:25', 0, NULL, '2026-11-08 08:42:58', '2026-11-08 20:54:25'),
 (106, 'JR-2026-0106', 6, 6, 4, 5, 3, 'Taman Kota Tanpa Penerangan', 'Taman tidak memiliki penerangan sehingga gelap dan tidak aman setelah magrib.', 'Simpang Jl. Sari Asih, Sukasari', -6.856798, 107.591787, 'sedang', 0, 'proses', NULL, 'sedang', '2026-11-07 11:17:46', '2026-11-13 11:17:46', '2026-11-06 12:04:41', 0, NULL, '2026-11-06 11:17:46', '2026-11-06 12:05:41'),
 (107, 'JR-2026-0107', 11, 1, 10, 1, 3, 'Lubang Jalan Menganga di Badan Jalan', 'Terdapat lubang sedalam kurang lebih 20 cm di tengah badan jalan. Pengendara motor sering mengerem mendadak dan beberapa nyaris terjatuh.', 'Dekat SD Negeri, Jl. Buah Batu, Batununggal', -6.924886, 107.6376, 'sedang', 0, 'selesai', '2026-10-25 06:00:02', 'sedang', '2026-10-22 00:00:18', '2026-10-28 00:00:18', '2026-10-21 10:21:48', 0, NULL, '2026-10-21 00:00:18', '2026-10-25 06:01:02'),
 (108, 'JR-2026-0108', 19, 3, 8, 3, 2, 'Sampah Menutupi Trotoar Pejalan Kaki', 'Tumpukan sampah menutup trotoar sehingga pejalan kaki harus berjalan di badan jalan.', 'Dekat SD Negeri, Jl. Pasir Kaliki, Cicendo', -6.905761, 107.59192, 'sedang', 0, 'selesai', '2026-10-04 09:37:19', 'sedang', '2026-09-30 20:57:53', '2026-10-06 20:57:53', '2026-09-30 17:15:38', 0, NULL, '2026-09-29 20:57:53', '2026-10-04 09:38:19'),
 (109, 'JR-2026-0109', 18, 3, 8, 3, NULL, 'Puing Bangunan Dibuang di Pinggir Jalan', 'Sisa material bangunan dibuang di pinggir jalan dan mengganggu lalu lintas serta pejalan kaki.', 'Simpang Jl. Pasir Kaliki, Cicendo', -6.909197, 107.591467, 'sedang', 0, 'ditolak', NULL, 'sedang', '2026-09-30 17:59:19', '2026-10-06 17:59:19', '2026-09-30 08:30:18', 0, NULL, '2026-09-29 17:59:19', '2026-09-30 08:31:18'),
 (110, 'JR-2026-0110', 9, 1, 7, 1, 2, 'Jalan Amblas Dekat Perempatan', 'Permukaan jalan turun sekitar 30 cm membentuk cekungan. Saat hujan cekungan terisi air sehingga lubangnya tidak terlihat pengendara.', 'Jl. Mohammad Toha No. 147, Bojongloa Kaler', -6.93269, 107.586733, 'bahaya', 0, 'selesai', '2026-10-30 12:16:53', 'darurat', '2026-10-28 23:47:37', '2026-10-31 11:47:37', '2026-10-28 22:39:07', 0, NULL, '2026-10-28 11:47:37', '2026-10-30 12:17:53'),
 (111, 'JR-2026-0111', 18, 2, 7, 2, 2, 'Lampu Jalan Padam di Dekat Sekolah', 'Lampu jalan di depan sekolah padam sehingga siswa yang pulang sore berjalan dalam gelap.', 'Jl. Babakan Ciparay No. 61, Bojongloa Kaler', -6.936399, 107.586232, 'sedang', 0, 'selesai', '2026-11-06 01:51:47', 'sedang', '2026-11-03 16:03:51', '2026-11-09 16:03:51', '2026-11-03 11:14:03', 0, NULL, '2026-11-02 16:03:51', '2026-11-06 01:52:47'),
 (112, 'JR-2026-0112', 15, 4, 2, 1, 2, 'Saluran Drainase Tersumbat Sampah', 'Drainase tersumbat sampah sehingga air menggenang setinggi mata kaki setiap kali hujan turun.', 'Samping Masjid, Jl. Gatot Subroto, Lengkong', -6.917223, 107.621218, 'sedang', 0, 'selesai', '2026-10-05 08:02:14', 'sedang', '2026-09-29 15:20:58', '2026-10-05 15:20:58', '2026-09-29 06:16:36', 0, NULL, '2026-09-28 15:20:58', '2026-10-05 08:03:14');
